import pytest

@pytest.mark.parametrize("num, expected", [(1, 1), (2, 4), (3, 9)])
def test_square(num, expected):
    assert num ** 2 == expected

def sort_list(lst):
    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

print(sort_list([3, 1, 5, 2, 8]))

def second_min(lst):
    first = second = float('inf')
    for num in lst:
        if num < first:
            second = first
            first = num
        elif num < second and num != first:
            second = num
    return second

print(second_min([5, 3, 1, 2, 4]))

class Calculator:
    base = 10

    def __init__(self, value):
        self.value = value

    def instance_method(self):
        return self.value

    @classmethod
    def class_method(cls):
        return cls.base

    @staticmethod
    def static_method(a, b):
        return a + b

c = Calculator(10)
print(f"Instance: {c.instance_method()}, Class: {c.class_method()}, Static: {c.static_method(5, 5)}")

def reverse_string(s):
    result = ''
    for i in range(len(s)-1, -1, -1):
        result += s[i]
    return result

print(reverse_string('wakefit'))

def group_consecutive(ids):
    if not ids:
        return []
    groups = [[ids[0]]]
    for i in range(1, len(ids)):
        if ids[i] == ids[i-1] + 1:
            groups[-1].append(ids[i])
        else:
            groups.append([ids[i]])
    return groups

print(group_consecutive([1, 2, 3, 7, 8, 12, 13, 14]))

def remove_duplicates(lst):
    seen = []
    for item in lst:
        if item not in seen:
            seen.append(item)
    return seen

print(remove_duplicates([3, 1, 4, 1, 5, 3, 1]))

def my_decorator(func):
    def wrapper():
        print("Before")
        func()
        print("After")
    return wrapper

@my_decorator
def greet():
    print("Hello")

greet()

def squares(n):
    for i in range(n):
        yield i * i

for val in squares(3):
    print(val, end=" ")

t = (1, 2, 3)
try:
    t[0] = 10
    print(t)
except TypeError:
    print("Error: tuples are immutable")
